From b30a092a46c194c58588023fda93c5814c21ed69 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:06:42 +0100
Subject: [PATCH] applets/lock_logout: space buttons like System Tray icons in
 panels

In a panel each button took a square as thick as the panel, so the icons
sat closer together than the System Tray's and almost touched on thicker
panels. Give each button the same icon size plus spacing as a tray cell.

BUG: 515693
---
 applets/lock_logout/main.qml | 7 +++++--
 1 file changed, 5 insertions(+), 2 deletions(-)

diff --git a/applets/lock_logout/main.qml b/applets/lock_logout/main.qml
index d89b3a0b43..c5253066d0 100644
--- a/applets/lock_logout/main.qml
+++ b/applets/lock_logout/main.qml
@@ -28,14 +28,14 @@ PlasmoidItem {
             if (Plasmoid.formFactor === PlasmaCore.Types.Vertical) {
                 return 0
             } else if (Plasmoid.formFactor === PlasmaCore.Types.Horizontal) {
-                return height < root.minButtonSize * visibleButtons ? height * visibleButtons : height / visibleButtons;
+                return height < root.minButtonSize * visibleButtons ? buttonLength * visibleButtons : height / visibleButtons;
             } else {
                 return width > height ? root.minButtonSize * visibleButtons : root.minButtonSize
             }
         }
         Layout.minimumHeight: {
             if (Plasmoid.formFactor === PlasmaCore.Types.Vertical) {
-                return width >= root.minButtonSize * visibleButtons ? width / visibleButtons : width * visibleButtons
+                return width >= root.minButtonSize * visibleButtons ? width / visibleButtons : buttonLength * visibleButtons
             } else if (Plasmoid.formFactor === PlasmaCore.Types.Horizontal) {
                 return 0
             } else {
@@ -46,6 +46,9 @@ PlasmoidItem {
         Layout.preferredWidth: Layout.minimumWidth
         Layout.preferredHeight: Layout.minimumHeight

+        readonly property int buttonThickness: Plasmoid.formFactor === PlasmaCore.Types.Vertical ? width : height
+        readonly property int buttonLength: Kirigami.Units.iconSizes.roundedIconSize(Math.min(buttonThickness, Kirigami.Units.iconSizes.enormous)) + Kirigami.Units.smallSpacing * 2
+
         readonly property int visibleButtons: {
             var count = 0
             for (var i = 0, j = items.count; i < j; ++i) {
-- 
2.53.0
